insert into clubs (name, location, website, disciplines, age_note, kids_only, founded, summary) values
  ('Mid Devon CC', 'Newton Abbot, Devon', 'https://www.middevon.cc', array['road','xc','cx']::club_discipline[], 'Go-Ride youth section, ages 8–16', false, '1930', 'One of the South West''s largest and longest-established clubs. British Cycling Go-Ride registered, with junior coaching across road, mountain bike and cyclocross sitting alongside a full adult racing programme — including hosting the Dartmoor Classic sportive.'),
  ('Wheal Velocity', 'Truro, Cornwall', 'https://www.whealvelocity.com', array['road','xc','cx']::club_discipline[], 'Junior Academy, Saturdays 1.30–4pm', false, null, 'Based at Wheal Jane''s traffic-free circuits near Truro, and widely regarded as the largest youth cycling club in the South West. Runs a Junior Academy, Development Squad and Race Team alongside road and off-road sessions for all ages.'),
  ('Exeter Wheelers', 'Exeter, Devon', 'https://www.exeterwheelers.co.uk', array['road']::club_discipline[], 'Exeter Wheelers Academy, ages 8+', false, '1924', 'A road-focused club founded in 1924, with a relaunched Youth Academy and British Cycling Go-Ride Focus Club status. Runs time trials, criteriums and a full programme of social and training rides year-round.'),
  ('North Devon Velo', 'Barnstaple, Devon', 'https://www.northdevonvelo.com', array['road','xc','cx']::club_discipline[], 'Youth section Saturdays at Petroc, under 16s', false, null, 'The only British Cycling Go-Ride accredited club in North Devon, formed from a merger of North Devon Wheelers and Taw Velo. Covers road, time trial, track, cyclocross and mountain biking, and hosts an SWCX round at Coxleigh Barton.'),
  ('Dartmoor Velo', 'Tavistock, Devon', 'https://www.dartmoorvelo.co.uk', array['road','xc','cx']::club_discipline[], 'Ages 8–16 — youth only, no adult section', true, null, 'A dedicated youth club covering West Devon and North Cornwall, with Saturday morning coaching in road, mountain bike and cyclocross for young riders. There''s no separate adult racing programme — it''s built around junior riders.');
